import{z as n,x as B,o as A,c as d,q as o,j as l,D as i,d as t,s as r,S as s,b as e}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"WiFi 6 / 7 与 OFDMA","description":"","frontmatter":{"title":"WiFi 6 / 7 与 OFDMA","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/wifi6-ofdma.md","filePath":"cs/wifi6-ofdma.md","lastUpdated":1791063341000}'),p={name:"cs/wifi6-ofdma.md"};function D(m,a,S,f,F,M){const E=B("Mermaid");return A(),d("div",null,[a[2]||(a[2]=o('<h1 id="wifi-6-7-与-ofdma" tabindex="-1">WiFi 6 / 7 与 OFDMA <a class="header-anchor" href="#wifi-6-7-与-ofdma" aria-label="Permalink to &quot;WiFi 6 / 7 与 OFDMA&quot;">​</a></h1><div class="epigraph"><p>OFDMA 把一次 TXOP 切成资源单元分给多个站点，降低争用；Wi‑Fi 7 再加多链路与 4K-QAM，仍在 802.11 MAC 里。</p><footer>—— 据 IEEE 802.11ax；IEEE 802.11be 草案条款整理</footer></div><p><a href="/cs/mimo-rate-adaptation">上一课</a> 一站点占满整段 OFDM 符号。密集 BSS 里争用主导延迟。缺口是 <strong>OFDMA</strong>：AP 当调度器，把子载波组（RU）分给不同 STA，上/下行都可。本课不把蓝牙跳频写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>DCF 下站点越多碰撞越多，MCS 再高也被队列与退避吃掉。11ax：触发帧启动上行 OFDMA，站点在指定 RU 发；下行同样按 RU 复用。这是把蜂窝里的调度借到 ISM 频段，仍无牌照、仍要听信道。Wi‑Fi 7（11be）：320 MHz、MLO 多链路聚合、4096-QAM——又一次在 \\(C\\) 下加压，对 SNR 与干扰更苛刻。</p><p><span class="marginnote">直觉类比：OFDM 像把一整节货车包给一个客户；OFDMA 像把车厢切成小隔间分给多户拼车——同一趟车（一个 TXOP）多户各占一格，谁也不用排队抢整车。</span></p><p>不要把 OFDMA 写成 5G 核心网：没有切片 SLA，只有 BSS 内调度。</p><p><span class="marginnote">802.11ax 引入 RU、BSS coloring。11be 的 MLO 与以太网 LACP 同类：多链路绑一条逻辑，但是空中。标准仍在演进，本课钉对象不钉某年芯片。</span></p><h3 id="ap-调度不是-5g-核心" tabindex="-1">AP 调度不是 5G 核心 <a class="header-anchor" href="#ap-调度不是-5g-核心" aria-label="Permalink to &quot;AP 调度不是 5G 核心&quot;">​</a></h3><p>RU 在一次 TXOP 里服务多站点，仍无牌照切片 SLA。Wi‑Fi 7 加压带宽与多链路，对 SNR 更苛刻。监管功率限制真实 \\(B\\)。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画：AP 调度 → RU 分配 → 多 STA 同符号。对照 CSMA：调度减少随机接入，不等于消除隐藏节点。MLO：一条链路上 MCS 差可走另一条，类似自适应但跨频段。</p>',12)),(A(),l(s,null,{default:i(()=>[r(E,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20AP%5B%22AP%20%E8%B0%83%E5%BA%A6%22%5D%20--%3E%20RU%5B%22%E8%B5%84%E6%BA%90%E5%8D%95%E5%85%83%22%5D%0A%20%20RU%20--%3E%20S1%5B%22%E7%AB%99%E7%82%B9%20A%22%5D%0A%20%20RU%20--%3E%20S2%5B%22%E7%AB%99%E7%82%B9%20B%22%5D%0A%20%20MLO%5B%22%E5%A4%9A%E9%93%BE%E8%B7%AF%22%5D%20--%3E%20LOG%5B%22%E4%B8%80%E6%9D%A1%E9%80%BB%E8%BE%91%E8%BF%9E%E6%8E%A5%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"有线 HOL 是结构；无线 HOL 常是整块信道被一个 STA 占满——OFDMA 对症。速率自适应仍按 RU 的 SNR 做。与 PFC 无关。主干 VLAN 可在 AP 上映射 SSID，不改 OFDMA。",-1)),a[5]||(a[5]=e("p",null,"BSS coloring：同频邻 BSS 可空间复用，干扰当噪声进 SNR。",-1)),a[6]||(a[6]=e("p",null,[e("span",{class:"marginnote"},"数字实例：一个 26-tone RU 只占 26 个子载波；20 MHz 信道的 242 个可用子载波理论上能同时分给 9 个站点——同一符号内 9 户并发，省下的是 8 轮退避等待。")],-1)),(A(),l(s,null,{default:i(()=>[r(E,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22AP%20%E5%B9%BF%E6%92%AD%E8%A7%A6%E5%8F%91%E5%B8%A7%EF%BC%9A%E5%88%97%E5%87%BA%20RU%20%E5%88%86%E9%85%8D%22%5D%20--%3E%20B%5B%22%E7%AB%99%E7%82%B9A%20%E5%9C%A8%20RU1%20%E5%8F%91%22%5D%0A%20%20A%20--%3E%20C%5B%22%E7%AB%99%E7%82%B9B%20%E5%9C%A8%20RU2%20%E5%8F%91%22%5D%0A%20%20A%20--%3E%20D%5B%22%E7%AB%99%E7%82%B9C%20%E5%9C%A8%20RU3%20%E5%8F%91%22%5D%0A%20%20B%20--%3E%20M%5B%22AP%20%E5%9C%A8%E5%90%8C%E4%B8%80%E7%AC%A6%E5%8F%B7%E5%86%85%E5%90%8C%E6%97%B6%E6%94%B6%22%5D%0A%20%20C%20--%3E%20M%0A%20%20D%20--%3E%20M%0A%20%20M%20--%3E%20BA%5B%22%E4%B8%80%E6%AC%A1%20Block%20ACK%20%E5%9B%9E%E5%A4%8D%E5%85%A8%E9%83%A8%22%5D%0A"})]),fallback:i(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=o('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 Wi‑Fi 与 5G 融合的全部 3GPP 附录。蓝牙与 BLE 是下一课。后课默认：11ax 起 AP 可按 RU 多用户复用。</p><p>监管功率与 DFS 雷达仍限制真实 \\(B\\)，标准表不是室内承诺。</p><p><span class="marginnote">常见误区：以为 4096-QAM 让家里网速必然大涨——星座点越密对 SNR 越苛刻，通常要离 AP 一两米内才吃得满；隔一堵墙会自动跌回 1024-QAM 甚至更低，速率是信道说了算，不是标准说了算。</span></p><p>下一课<a href="/cs/bluetooth-ble">蓝牙与 BLE</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>OFDMA 用 RU 在一次发送里服务多站点。</li><li>Wi‑Fi 7 加压带宽、星座与多链路。</li><li>仍是 802.11 争用+调度，不是运营商核心网。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：IEEE 802.11ax；802.11be。</li></ul>',7))])}const u=n(p,[["render",D]]);export{P as __pageData,u as default};
